import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testAddition() {
        Assert.assertEquals(7, applyOperation(3, 4, { x, y -> x + y }))
    }

    @Test
    fun testMultiplication() {
        Assert.assertEquals(30, applyOperation(10, 3, { x, y -> x * y }))
    }

    @Test
    fun testSubtraction() {
        Assert.assertEquals(5, applyOperation(8, 3, { x, y -> x - y }))
    }

    @Test
    fun testMax() {
        Assert.assertEquals(42, applyOperation(42, 17, { x, y -> if (x > y) x else y }))
    }
}
